## Design Note

The decoder is a character-by-character finite state machine fed by `feed()`. A single `_state` variable plus sub-states (string/number/literal) plus a container stack drives transitions. Each character is examined exactly once — total work is O(n) in stream length regardless of chunking. The raw text of each top-level value is accumulated in a list; once boundaries are known, `json.loads` decodes it. A running `_val_len` counter enforces the buffer limit. `pending()` reads `_val_len`. Errors carry absolute offsets tracked by `_offset`.

### solution.py
```python
"""Incremental JSON stream splitter for log ingestion (RFC 8259, stdlib only)."""

import json
from typing import Any

__all__ = [
    "JSONStreamError",
    "IncompleteJSONError",
    "BufferLimitError",
    "JSONStreamDecoder",
]


class JSONStreamError(ValueError):
    """Raised when the stream is invalid."""
    def __init__(self, msg: str = "", offset: int = 0):
        super().__init__(msg)
        self.offset = offset


class IncompleteJSONError(JSONStreamError):
    """Raised by close() when a value is unfinished."""


class BufferLimitError(JSONStreamError):
    """Raised when a single top-level value exceeds max_buffer."""


# ---------------------------------------------------------------------------
# Internal helpers
# ---------------------------------------------------------------------------

_WS = frozenset(' \t\n\r')

# Top-level terminator set: whitespace, '{', '[', '"'
def _is_top_terminator(ch: str) -> bool:
    return ch in _WS or ch in '{["'

# In-container terminator set: whitespace, ',', '}', ']'
def _is_container_terminator(ch: str) -> bool:
    return ch in _WS or ch in ',}]'

_HEX = frozenset('0123456789abcdefABCDEF')
_LITERALS = ('true', 'false', 'null')


class JSONStreamDecoder:
    """Feed raw text chunks; receive complete top-level JSON values."""

    # ---- public API -------------------------------------------------------

    def __init__(self, *, max_buffer: int = 10_000_000) -> None:
        if isinstance(max_buffer, bool) or not isinstance(max_buffer, int) or max_buffer < 1:
            raise ValueError("max_buffer must be an int >= 1")
        self._max_buffer = max_buffer
        self._offset: int = 0          # absolute offset of *next* char to be consumed
        self._errored = False
        self._closed = False

        # Main state
        self._mode: int = 0            # 0=BETWEEN 1=TOP_VAL 2=CONTAINER 3=IN_VAL

        # Top-level value text buffer & bookkeeping
        self._buf: list[str] = []
        self._value_start: int = 0
        self._val_len: int = 0

        # Container stack: list of (type, expect)
        #   type: 'o'=object, 'a'=array
        #   expect: 'k'=key, ':'=colon, 'v'=value, 'c'=comma/closing
        self._stack: list[tuple[str, str]] = []

        # Value sub-state (active in TOP_VAL / IN_VAL)
        self._vkind: str = ''          # 's'=string 'n'=number 'l'=literal
        self._ss: str = ''             # string sub-state: '' 'e' 'u1' 'u2' 'u3' 'u4'
        self._ns: str = ''             # number sub-state
        self._lit: str = ''            # target literal text
        self._lp: int = 0              # literal match position
        self._is_key: bool = False     # current string is an object key

    def feed(self, chunk: str) -> list[Any]:
        if not isinstance(chunk, str):
            raise TypeError(f"chunk must be str, got {type(chunk).__name__}")
        if self._errored:
            raise JSONStreamError("decoder is unusable after error", self._offset)
        if self._closed:
            raise JSONStreamError("decoder is closed", self._offset)
        if not chunk:
            return []
        results: list[Any] = []
        for ch in chunk:
            self._step(ch, results)
            self._offset += 1
        return results

    def close(self) -> list[Any]:
        if self._errored:
            raise JSONStreamError("decoder is unusable after error", self._offset)
        if self._closed:
            raise JSONStreamError("decoder is already closed", self._offset)
        self._closed = True
        # Check for pending incomplete value
        if self._mode == 0:
            return []
        # In TOP_VAL: number/literal that is syntactically complete → emit
        if self._mode == 1:
            if self._vkind == 'n' and self._num_is_complete():
                results = self._emit_top()
                return results
            if self._vkind == 'l' and self._lit_complete():
                results = self._emit_top()
                return results
            # string in progress
            raise IncompleteJSONError("incomplete value at end of stream", self._offset)
        if self._mode == 2:
            raise IncompleteJSONError("incomplete container at end of stream", self._offset)
        if self._mode == 3:
            # in-container value in progress → container is incomplete
            raise IncompleteJSONError("incomplete value at end of stream", self._offset)
        return []

    def pending(self) -> int:
        if self._mode == 0:
            return 0
        return self._val_len

    # ---- state machine: one character at a time ---------------------------

    def _step(self, ch: str, results: list[Any]) -> None:
        mode = self._mode
        if mode == 0:
            self._between(ch, results)
        elif mode == 1:
            self._top_val(ch, results)
        elif mode == 2:
            self._container(ch, results)
        elif mode == 3:
            self._in_val(ch, results)

    # ---- BETWEEN ----------------------------------------------------------

    def _between(self, ch: str, results: list[Any]) -> None:
        if ch in _WS:
            return
        if ch == '{':
            self._begin_value()
            self._buf.append(ch)
            self._stack.append(('o', 'k'))
            self._mode = 2
            return
        if ch == '[':
            self._begin_value()
            self._buf.append(ch)
            self._stack.append(('a', 'v'))
            self._mode = 2
            return
        if ch == '"':
            self._begin_value()
            self._buf.append(ch)
            self._vkind = 's'
            self._ss = ''
            self._mode = 1
            return
        if ch == '-' or ('0' <= ch <= '9'):
            self._begin_value()
            self._buf.append(ch)
            self._vkind = 'n'
            if ch == '-':
                self._ns = 'ms'
            elif ch == '0':
                self._ns = 'z'
            else:
                self._ns = 'int'
            self._mode = 1
            return
        if ch == 't':
            self._begin_value()
            self._buf.append(ch)
            self._vkind = 'l'
            self._lit = 'true'
            self._lp = 1
            self._mode = 1
            return
        if ch == 'f':
            self._begin_value()
            self._buf.append(ch)
            self._vkind = 'l'
            self._lit = 'false'
            self._lp = 1
            self._mode = 1
            return
        if ch == 'n':
            self._begin_value()
            self._buf.append(ch)
            self._vkind = 'l'
            self._lit = 'null'
            self._lp = 1
            self._mode = 1
            return
        # ']', '}', ',', ':', letters, etc. → error
        raise JSONStreamError(f"unexpected character {ch!r}", self._offset)

    # ---- TOP_VAL (top-level string / number / literal) -------------------

    def _top_val(self, ch: str, results: list[Any]) -> None:
        kind = self._vkind
        if kind == 's':
            self._string_content(ch, results, top=True)
        elif kind == 'n':
            self._number_top(ch, results)
        elif kind == 'l':
            self._literal_top(ch, results)

    # ---- CONTAINER --------------------------------------------------------

    def _container(self, ch: str, results: list[Any]) -> None:
        typ, expect = self._stack[-1]
        if expect == 'k':  # object: expect key
            self._cont_expect_key(ch, results)
        elif expect == ':':  # object: expect colon
            self._cont_expect_colon(ch, results)
        elif expect == 'v':  # expect value
            self._cont_expect_value(ch, results)
        elif expect == 'c':  # expect comma or closing
            self._cont_expect_comma_end(ch, results)

    # ---- IN_VAL (value parsing inside a container) ------------------------

    def _in_val(self, ch: str, results: list[Any]) -> None:
        kind = self._vkind
        if kind == 's':
            self._string_content(ch, results, top=False)
        elif kind == 'n':
            self._number_in(ch, results)
        elif kind == 'l':
            self._literal_in(ch, results)

    # ===================================================================
    # String parsing
    # ===================================================================

    def _string_content(self, ch: str, results: list[Any], *, top: bool) -> None:
        self._buf.append(ch)
        self._val_len += 1
        self._check_buffer()

        ss = self._ss
        if ss == '':
            if ch == '"':
                # string complete
                self._val_len -= 1
                self._buf.pop()  # remove closing quote for length calc
                self._val_len += 1  # it's part of the value
                self._finish_string(top, results)
            elif ch == '\\':
                self._ss = 'e'
            elif ord(ch) < 0x20:
                raise JSONStreamError("unescaped control character in string", self._offset)
            # else: normal char, stay in ''
        elif ss == 'e':
            if ch in ('"', '\\', '/', 'b', 'f', 'n', 'r', 't'):
                self._ss = ''
            elif ch == 'u':
                self._ss = 'u1'
            else:
                raise JSONStreamError(f"invalid escape \\{ch!r}", self._offset)
        elif ss == 'u1':
            if ch in _HEX:
                self._ss = 'u2'
            else:
                raise JSONStreamError(f"invalid unicode escape hex digit {ch!r}", self._offset)
        elif ss == 'u2':
            if ch in _HEX:
                self._ss = 'u3'
            else:
                raise JSONStreamError(f"invalid unicode escape hex digit {ch!r}", self._offset)
        elif ss == 'u3':
            if ch in _HEX:
                self._ss = 'u4'
            else:
                raise JSONStreamError(f"invalid unicode escape hex digit {ch!r}", self._offset)
        elif ss == 'u4':
            if ch in _HEX:
                self._ss = ''
            else:
                raise JSONStreamError(f"invalid unicode escape hex digit {ch!r}", self._offset)

    def _finish_string(self, top: bool, results: list[Any]) -> None:
        if top:
            self._emit_top_into(results)
        else:
            self._mode = 2
            typ, expect = self._stack[-1]
            if self._is_key:
                self._stack[-1] = (typ, ':')
            else:
                self._stack[-1] = (typ, 'c')
            self._vkind = ''
            self._ss = ''

    # ===================================================================
    # Number parsing
    # ===================================================================

    def _number_top(self, ch: str, results: list[Any]) -> None:
        ns = self._ns
        # Check for terminator first (before consuming)
        if _is_top_terminator(ch):
            # number is complete; terminator NOT part of value
            self._emit_top_into(results)
            # re-dispatch terminator as start of new value / whitespace
            self._between(ch, results)
            return
        # Must continue the number
        self._buf.append(ch)
        self._val_len += 1
        self._check_buffer()

        if ns == 'ms':  # after '-'
            if '0' <= ch <= '9':
                self._ns = 'z' if ch == '0' else 'int'
            else:
                raise JSONStreamError(f"invalid character after '-' in number: {ch!r}", self._offset)
        elif ns == 'z':  # leading zero – no more digits
            raise JSONStreamError(f"leading zero in number: {ch!r}", self._offset)
        elif ns == 'int':
            if '0' <= ch <= '9':
                pass  # stay 'int'
            elif ch == '.':
                self._ns = 'dot'
            elif ch in ('e', 'E'):
                self._ns = 'exp'
            else:
                raise JSONStreamError(f"invalid character in number: {ch!r}", self._offset)
        elif ns == 'dot':
            if '0' <= ch <= '9':
                self._ns = 'frac'
            else:
                raise JSONStreamError(f"invalid character after '.' in number: {ch!r}", self._offset)
        elif ns == 'frac':
            if '0' <= ch <= '9':
                pass
            elif ch in ('e', 'E'):
                self._ns = 'exp'
            else:
                raise JSONStreamError(f"invalid character in number: {ch!r}", self._offset)
        elif ns == 'exp':
            if ch in ('+', '-'):
                self._ns = 'exps'
            elif '0' <= ch <= '9':
                self._ns = 'expd'
            else:
                raise JSONStreamError(f"invalid character after exponent: {ch!r}", self._offset)
        elif ns == 'exps':
            if '0' <= ch <= '9':
                self._ns = 'expd'
            else:
                raise JSONStreamError(f"invalid character in exponent: {ch!r}", self._offset)
        elif ns == 'expd':
            if '0' <= ch <= '9':
                pass
            else:
                raise JSONStreamError(f"invalid character in exponent: {ch!r}", self._offset)

    def _number_in(self, ch: str, results: list[Any]) -> None:
        ns = self._ns
        if _is_container_terminator(ch):
            # number complete inside container
            self._finish_number_in(results)
            # re-dispatch terminator in container mode
            self._container(ch, results)
            return
        self._buf.append(ch)
        self._val_len += 1
        self._check_buffer()

        if ns == 'ms':
            if '0' <= ch <= '9':
                self._ns = 'z' if ch == '0' else 'int'
            else:
                raise JSONStreamError(f"invalid character after '-' in number: {ch!r}", self._offset)
        elif ns == 'z':
            raise JSONStreamError(f"leading zero in number: {ch!r}", self._offset)
        elif ns == 'int':
            if '0' <= ch <= '9':
                pass
            elif ch == '.':
                self._ns = 'dot'
            elif ch in ('e', 'E'):
                self._ns = 'exp'
            else:
                raise JSONStreamError(f"invalid character in number: {ch!r}", self._offset)
        elif ns == 'dot':
            if '0' <= ch <= '9':
                self._ns = 'frac'
            else:
                raise JSONStreamError(f"invalid character after '.' in number: {ch!r}", self._offset)
        elif ns == 'frac':
            if '0' <= ch <= '9':
                pass
            elif ch in ('e', 'E'):
                self._ns = 'exp'
            else:
                raise JSONStreamError(f"invalid character in number: {ch!r}", self._offset)
        elif ns == 'exp':
            if ch in ('+', '-'):
                self._ns = 'exps'
            elif '0' <= ch <= '9':
                self._ns = 'expd'
            else:
                raise JSONStreamError(f"invalid character after exponent: {ch!r}", self._offset)
        elif ns == 'exps':
            if '0' <= ch <= '9':
                self._ns = 'expd'
            else:
                raise JSONStreamError(f"invalid character in exponent: {ch!r}", self._offset)
        elif ns == 'expd':
            if '0' <= ch <= '9':
                pass
            else:
                raise JSONStreamError(f"invalid character in exponent: {ch!r}", self._offset)

    def _num_is_complete(self) -> bool:
        return self._ns in ('int', 'z', 'frac', 'expd')

    def _finish_number_in(self, results: list[Any]) -> None:
        self._mode = 2
        typ, _ = self._stack[-1]
        self._stack[-1] = (typ, 'c')
        self._vkind = ''
        self._ns = ''

    # ===================================================================
    # Literal parsing
    # ===================================================================

    def _literal_top(self, ch: str, results: list[Any]) -> None:
        # Check terminator first
        if _is_top_terminator(ch):
            self._emit_top_into(results)
            self._between(ch, results)
            return
        # Continue matching literal
        if self._lp < len(self._lit) and ch == self._lit[self._lp]:
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._lp += 1
            if self._lp == len(self._lit):
                # literal complete, waiting for terminator
                pass  # stay in TOP_VAL with vkind='l', lp==len
        else:
            raise JSONStreamError(f"invalid literal: expected {self._lit[self._lp] if self._lp < len(self._lit) else 'terminator'!r}, got {ch!r}", self._offset)

    def _literal_in(self, ch: str, results: list[Any]) -> None:
        if _is_container_terminator(ch):
            self._finish_literal_in(results)
            self._container(ch, results)
            return
        if self._lp < len(self._lit) and ch == self._lit[self._lp]:
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._lp += 1
        else:
            raise JSONStreamError(f"invalid literal: expected {self._lit[self._lp] if self._lp < len(self._lit) else 'terminator'!r}, got {ch!r}", self._offset)

    def _lit_complete(self) -> bool:
        return self._lp == len(self._lit)

    def _finish_literal_in(self, results: list[Any]) -> None:
        self._mode = 2
        typ, _ = self._stack[-1]
        self._stack[-1] = (typ, 'c')
        self._vkind = ''

    # ===================================================================
    # Container sub-states
    # ===================================================================

    def _cont_expect_key(self, ch: str, results: list[Any]) -> None:
        if ch in _WS:
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            return
        if ch == '}':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._close_container(results)
            return
        if ch == '"':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._vkind = 's'
            self._ss = ''
            self._is_key = True
            self._mode = 3
            return
        raise JSONStreamError(f"expected string key, got {ch!r}", self._offset)

    def _cont_expect_colon(self, ch: str, results: list[Any]) -> None:
        if ch in _WS:
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            return
        if ch == ':':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            typ = self._stack[-1][0]
            self._stack[-1] = (typ, 'v')
            return
        raise JSONStreamError(f"expected ':', got {ch!r}", self._offset)

    def _cont_expect_value(self, ch: str, results: list[Any]) -> None:
        if ch in _WS:
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            return
        if ch == '{':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._stack.append(('o', 'k'))
            return
        if ch == '[':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._stack.append(('a', 'v'))
            return
        if ch == '"':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._vkind = 's'
            self._ss = ''
            self._is_key = False
            self._mode = 3
            return
        if ch == '-' or ('0' <= ch <= '9'):
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._vkind = 'n'
            if ch == '-':
                self._ns = 'ms'
            elif ch == '0':
                self._ns = 'z'
            else:
                self._ns = 'int'
            self._mode = 3
            return
        if ch == 't':
            self._begin_in_val('true', ch)
            self._mode = 3
            return
        if ch == 'f':
            self._begin_in_val('false', ch)
            self._mode = 3
            return
        if ch == 'n':
            self._begin_in_val('null', ch)
            self._mode = 3
            return
        raise JSONStreamError(f"expected value, got {ch!r}", self._offset)

    def _cont_expect_comma_end(self, ch: str, results: list[Any]) -> None:
        typ, _ = self._stack[-1]
        if ch in _WS:
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            return
        if ch == ',':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            if typ == 'o':
                self._stack[-1] = (typ, 'k')
            else:
                self._stack[-1] = (typ, 'v')
            return
        if typ == 'o' and ch == '}':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._close_container(results)
            return
        if typ == 'a' and ch == ']':
            self._buf.append(ch)
            self._val_len += 1
            self._check_buffer()
            self._close_container(results)
            return
        raise JSONStreamError(f"expected ',' or closing bracket, got {ch!r}", self._offset)

    def _close_container(self, results: list[Any]) -> None:
        self._stack.pop()
        if not self._stack:
            # top-level value complete
            self._emit_top_into(results)
        else:
            typ = self._stack[-1][0]
            self._stack[-1] = (typ, 'c')
            self._mode = 2

    def _begin_in_val(self, target: str, ch: str) -> None:
        self._buf.append(ch)
        self._val_len += 1
        self._check_buffer()
        self._vkind = 'l'
        self._lit = target
        self._lp = 1

    # ===================================================================
    # Helpers
    # ===================================================================

    def _begin_value(self) -> None:
        self._buf = []
        self._val_len = 1  # the first char is counted by caller
        self._value_start = self._offset
        self._mode = 0  # temporary; caller overrides

    def _check_buffer(self) -> None:
        if self._val_len > self._max_buffer:
            raise BufferLimitError(
                f"top-level value exceeds max_buffer ({self._max_buffer})",
                self._value_start + self._max_buffer,
            )

    def _emit_top(self) -> list[Any]:
        text = ''.join(self._buf)
        val = json.loads(text)
        self._reset_after_value()
        return [val]

    def _emit_top_into(self, results: list[Any]) -> None:
        text = ''.join(self._buf)
        val = json.loads(text)
        results.append(val)
        self._reset_after_value()

    def _reset_after_value(self) -> None:
        self._buf = []
        self._val_len = 0
        self._mode = 0
        self._vkind = ''
        self._ss = ''
        self._ns = ''
        self._lit = ''
        self._lp = 0
        self._is_key = False
```

### test_solution.py
```python
"""Tests for solution.JSONStreamDecoder."""

import pytest
import solution
from solution import (
    JSONStreamDecoder,
    JSONStreamError,
    IncompleteJSONError,
    BufferLimitError,
)
import math


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def feed_all(d: JSONStreamDecoder, text: str, chunk_size: int = 64) -> list:
    """Feed text in small chunks, collecting all results."""
    results = []
    for i in range(0, len(text), chunk_size):
        results.extend(d.feed(text[i:i + chunk_size]))
    results.extend(d.close())
    return results


def feed_one(d: JSONStreamDecoder, text: str) -> list:
    return d.feed(text)


# ---------------------------------------------------------------------------
# Basic value parsing
# ---------------------------------------------------------------------------

class TestBasic:
    def test_empty_stream(self):
        d = JSONStreamDecoder()
        assert d.feed("") == []
        assert d.close() == []

    def test_single_object(self):
        d = JSONStreamDecoder()
        assert d.feed('{"a":1}') == [{"a": 1}]
        assert d.close() == []

    def test_single_array(self):
        d = JSONStreamDecoder()
        assert d.feed('[1,2,3]') == [[1, 2, 3]]
        assert d.close() == []

    def test_single_string(self):
        d = JSONStreamDecoder()
        assert d.feed('"hello"') == ["hello"]
        assert d.close() == []

    def test_single_number_int(self):
        d = JSONStreamDecoder()
        assert d.feed('42 ') == [42]
        assert d.close() == []

    def test_single_number_float(self):
        d = JSONStreamDecoder()
        assert d.feed('3.14 ') == [3.14]
        assert d.close() == []

    def test_single_true(self):
        d = JSONStreamDecoder()
        assert d.feed('true ') == [True]

    def test_single_false(self):
        d = JSONStreamDecoder()
        assert d.feed('false ') == [False]

    def test_single_null(self):
        d = JSONStreamDecoder()
        assert d.feed('null ') == [None]

    def test_heartbeat_int(self):
        d = JSONStreamDecoder()
        assert d.feed('7 ') == [7]

    def test_heartbeat_bool(self):
        d = JSONStreamDecoder()
        assert d.feed('true\n') == [True]

    def test_multiple_values(self):
        d = JSONStreamDecoder()
        r = d.feed('1 2 3 ')
        assert r == [1, 2, 3]

    def test_no_whitespace_separation(self):
        d = JSONStreamDecoder()
        r = d.feed('{}[]"x"1 ')
        assert r == [{}, [], "x", 1]

    def test_number_then_array(self):
        d = JSONStreamDecoder()
        r = d.feed('1[2]')
        assert r == [1, [2]]

    def test_true_then_string(self):
        d = JSONStreamDecoder()
        r = d.feed('true"x"')
        assert r == [True, "x"]

    def test_negative_number(self):
        d = JSONStreamDecoder()
        assert d.feed('-123 ') == [-123]

    def test_number_exponent(self):
        d = JSONStreamDecoder()
